func Activate() witTypes.Result[witTypes.Unit, string] {
	result := diagnosticsReporting.Submit(diagnosticsTypes.Report{
		Level:   diagnosticsTypes.Level_Info,
		Source:  "rc.scheduler",
		Code:    "scheduler.active",
		Message: "portable scheduler activated",
		Fields: []diagnosticsTypes.Field{
			{Name: "timezone_database", Value: "iana"},
			{Name: "overlap_default", Value: "forbid"},
		},
	})
	if result.IsErr() {
		return witTypes.Err[witTypes.Unit, string](result.Err())
	}
	return witTypes.Ok[witTypes.Unit, string](witTypes.Unit{})
}

